import unittest
from src.digest import summarize_day
from src.bands import classify_pm25

class DigestChecks(unittest.TestCase):
    def test_day_averages_before_band(self):
        self.assertEqual(summarize_day([8, 32]), {"band": "hazy", "samples": 2})
    def test_clear_boundary(self):
        self.assertEqual(classify_pm25(12), "clear")
